INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:152','mayalex_normativos','10_LEYES_REGLAMENTOS','Los servicios públicos que las Municipalidades proporcionan a la comunidad, pueden ser: a) Regulares; b) Permanentes; y c) Eventuales.

a) Son servicios regulares:

1) La recolección de basura;
2) El servicio de bomberos

3) El alumbrado público
4) El suministro de energía eléctrica residencial, comercial industrial, etc.
5) El agua potable
6) El alcantarillado pluvial y sanitario, teléfonos y
7) Otros similares.

b) Dentro de los servicios permanentes que las Municipalidades ofrecen al público, mediante las instalaciones aprobadas están:

1) Locales y facilidades en mercados públicos y centros comerciales
2) Utilización de cementerios públicos
3) Estacionamiento de vehículos en lugares acondicionados y uso de parquímetro
4) Utilización de locales para destace de ganado; y
5) Otros similares.

c) Entre los servicios eventuales que las Municipalidades prestan al público están:

1) Autorización de libros contables y otros;
2) Permiso de operación de negocios y sus renovaciones, construcción de edificios, lotificaciones y otros;
3) La planificación, organización y administración de los servicios públicos municipales. Extensión de permisos para espectáculos públicos, exhibiciones, exposiciones, etc.
4) Tramitación y celebración de matrimonios civiles
5) Matriculas de vehículos, armas de fuego, etc.
6) Licencia de agricultores, ganaderos, destazadores y otros;

7) Elaboración de levantamientos topográficos y lotificaciones para áreas marginales y colonias intervenidas y recuperadas por la Municipalidad.
8) Elaboración de planos y diseños de elementos constructivos
9) Inspección de las construcciones a que se refiere el numeral 2 del presente literal;
10) Extensión de certificaciones, constancias y transcripciones de los actos propios de la Alcaldía;
11) Limpieza de solares baldíos.
12) Ocupación, apertura, y reparación de aceras y vías publicas
13) Colocación de rótulos y vallas publicitarias;
14) Extensión de permisos de buhoneros, casetas de venta;
15) Licencia para explotación de productos naturales;
16) Autorización de cartas de venta de ganado;
17) Registros de fierros de herrar ganado.
18) Guías de traslado de ganado entre Departamentos o Municipios; y
19) Otros similares.','152','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":151,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"3b282e7023f05962c7e4f6a9a7dc17d61be4c9726ca4d68c37e9713d8c5e555d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','152','3b282e7023f05962c7e4f6a9a7dc17d61be4c9726ca4d68c37e9713d8c5e555d','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:153','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Municipalidades cobrarán los valores por concepto de tasas de servicios públicos utilizando los procedimientos y controles que estimen conveniente y que se ajusten a los métodos convencionales de tales prácticas.','153','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":152,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"ff3cae388e62fef12357181ef9bb8c7330d0a58017c277f4aec55aaffd2a1e59","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','153','ff3cae388e62fef12357181ef9bb8c7330d0a58017c277f4aec55aaffd2a1e59','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:154','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Municipalidades aplicarán una multa de diez por ciento (10%) del impuesto a pagar en su caso, por el incumplimiento de las siguientes disposiciones:

a) Presentación de las declaraciones juradas del Impuesto personal después del mes de abril;
b) Presentación de las declaraciones juradas del Impuesto sobre la extracción o de explotación de recursos después del mes de enero, si la actividad es permanente y después de un (1) mes de iniciada la explotación si la actividad es de carácter eventual.','154','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":153,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"d921aa70d096f555c79ba651d134d29652f5a2bc8f8572e37b78d50729f45a73","ubicacion":["SECCION OCTAVA","SANCIONES Y MULTAS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','154','d921aa70d096f555c79ba651d134d29652f5a2bc8f8572e37b78d50729f45a73','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:155','mayalex_normativos','10_LEYES_REGLAMENTOS','Se aplicará una multa equivalente al impuesto correspondiente a un mes por el incumplimiento de:

a) Presentación de las declaraciones juradas del impuesto sobre industrias, comercios y Servicio después del mes de enero;
b) Por no haberse presentado a tiempo la declaración jurada al efectuar el traspaso, cambio de domicilio, modificación o ampliación de la actividad económica de un negocio;

c) Por la representación fuera de tiempo del estimado de ingreso del primer trimestre en el caso de apertura de un negocio y,
d) Por no haber presentado la declaración jurada de los ingresos dentro de treinta (30) días siguientes a la clausura, cierre liquidación o suspensión de un negocio.','155','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":154,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"054f3f3f2f4d41d99009314fa6f68152061103abf9c57a73f45e1b1943bd8ae8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','155','054f3f3f2f4d41d99009314fa6f68152061103abf9c57a73f45e1b1943bd8ae8','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:156','mayalex_normativos','10_LEYES_REGLAMENTOS','La presentación de una declaración jurada con información y datos falsos, con objeto de evadir el pago correcto del tributo municipal, se sancionará con una multa igual al cien por ciento (100%) de impuesto a pagar, sin perjuicio de pago del impuesto correspondiente.','156','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":155,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"414f6708bee5a41a71f0d28afba65464c0957c68fe5851a763cbeb38bebbfcae","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','156','414f6708bee5a41a71f0d28afba65464c0957c68fe5851a763cbeb38bebbfcae','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:157','mayalex_normativos','10_LEYES_REGLAMENTOS','Se aplicará una multa entre cincuenta Lempiras (L.50.00) a quinientos Lempiras (L.500.00) al propietario o responsable de un negocio que opere sin el permiso de Operación de Negocios correspondiente. Si transcurrido un mes de haberse impuesto la mencionada sanción no hubiere adquirido el respectivo permiso, se le aplicará el doble de multa impuesta. En caso que persista el incumplimiento, se procederá al cierre y clausura definitiva del negocio.','157','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":156,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"1a1391d683f1b961b1a8ed9290d86027076511381961b02f164821ec109df92e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','157','1a1391d683f1b961b1a8ed9290d86027076511381961b02f164821ec109df92e','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:158','mayalex_normativos','10_LEYES_REGLAMENTOS','La persona natural o jurídica que no obtenga de parte de Municipalidad su respectiva licencia de extracción o explotación de recursos, no podrá desarrollar su actividad de explotación. En caso que ejerciera dicha actividad sin la respectiva licencia, se le multará, por primera vez, con una cantidad entre Quinientos Lempiras (L. 500.00) a diez mil Lempiras (L.10.000.00), según sea la importancia de los recursos a explotar así como la confiscación total de los recursos explotados ilegalmente, en caso de reincidencia, se le sancionará cada vez con el doble de la multa impuesta por primera vez.','158','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":157,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"a333365ce5732998180aa9c32f4375e6a90e7ad7cfdcec6e3b433636da58b2b8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','158','a333365ce5732998180aa9c32f4375e6a90e7ad7cfdcec6e3b433636da58b2b8','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:159','mayalex_normativos','10_LEYES_REGLAMENTOS','Los contribuyentes sujetos al impuesto sobre Bienes Inmuebles que no presentaren en tiempo la declaración jurada establecida en este Reglamento, se le sancionará con una multa del diez por ciento (10%) del impuesto a pagar, por el primer mes y uno por ciento (1%) mensual a partir del 2do. Mes.','159','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":158,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"37181abaa980eeeb2abfe5eec2b2e13a953684bc6367373d8a89045c01a1fcc2","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','159','37181abaa980eeeb2abfe5eec2b2e13a953684bc6367373d8a89045c01a1fcc2','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:160','mayalex_normativos','10_LEYES_REGLAMENTOS','Las personas expresadas en el artículo 126 del presente Reglamento que no proporcionen la información requerida por escrito por el personal autorizado, se le aplicará una multa de Cincuenta Lempiras (L.50.00) por cada día que atrase la respectiva información. El requerimiento de la información debe hacerse por escrito con las formalidades establecidas por la Municipalidad.','160','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":159,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"b7f34538c740cee001e3f86db853fa7f22ca33691b3d2e61e1e3b65297538dc2","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','160','b7f34538c740cee001e3f86db853fa7f22ca33691b3d2e61e1e3b65297538dc2','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:161','mayalex_normativos','10_LEYES_REGLAMENTOS','El pago extemporáneo de los impuestos y tasas por servicios municipales establecidos por la Ley a que se refiere el presente reglamento, se sancionará con un recargo de intereses del uno por ciento (1%) mensual sobre la cantidad el impuesto o tasa pendiente de pago. En el caso del impuesto sobre Bienes inmuebles, además de este porcentaje de intereses se aplicará el dos por ciento (2%) mensual de recargo por mora según lo establecido en el artículo 76 de la Ley.','161','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":160,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"db451a4dbe5db5db5e18794a9863ea7324d4f70c80cfd428026336dd69cd1a77","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','161','db451a4dbe5db5db5e18794a9863ea7324d4f70c80cfd428026336dd69cd1a77','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:162','mayalex_normativos','10_LEYES_REGLAMENTOS','El patrono que sin causa justificada no retenga el impuesto respectivo a que este obligado el contribuyente, pagara una multa equivalente al veinticinco por ciento (25%) del impuesto no retenido.','162','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":161,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"199015a49d11f9c8ed5f01b8adfb13c1443cc89ea44cb3c4202c4d48847dc89e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','162','199015a49d11f9c8ed5f01b8adfb13c1443cc89ea44cb3c4202c4d48847dc89e','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:163','mayalex_normativos','10_LEYES_REGLAMENTOS','Cuando el patrono sin ninguna justificación, no deposite las cantidades retenidas por concepto de impuesto y tasas, en los plazos legalmente establecidos, la Municipalidad le impondrá una multa equivalente al tres por ciento (3%) mensual sobre las cantidades retenidas y no enteradas en el plazo señalado','163','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":162,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"8d269f825d1b779b605cc49f43dd91fae9c6c4c4630197b051adc35d8f6ac6e5","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','163','8d269f825d1b779b605cc49f43dd91fae9c6c4c4630197b051adc35d8f6ac6e5','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:164','mayalex_normativos','10_LEYES_REGLAMENTOS','En los respectivos Planes de Arbitrios, las municipalidades establecerán las demás sanciones y multas que deben aplicarse por las informaciones o incumplimientos de los actos, mandatos o trámites obligatorios ordenados en dichos Planes de Arbitrios.','164','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":163,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"e969c3263156302426e3ec5d9f9f30f62ffe5fd6a75c08cfd593cb2a04791b18","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','164','e969c3263156302426e3ec5d9f9f30f62ffe5fd6a75c08cfd593cb2a04791b18','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:165','mayalex_normativos','10_LEYES_REGLAMENTOS','Los contribuyentes sujetos a los impuestos y tasas municipales podrán pagar dichos tributos en forma anticipada. Siempre que ese pago se efectúe totalmente con cuatro o más meses de anticipación al plazo legal, los contribuyentes tendrán derecho a que la Municipalidad les conceda un descuento del diez por ciento (10%) del total del tributo pagado en forma anticipada.

Por consiguiente, para tener derecho a este descuento los tributos deben pagarse a más tardar:

a) El impuesto sobre bienes inmuebles, en el mes de abril o antes;
b) El impuesto personal, en el mes de enero o antes;
c) El impuesto sobre industrias, Comercios, y Servicios, en el mes de Septiembre del año anterior o antes, cuando se pague por todo el año, y en forma proporcional, cuando el pago se efectúe después de esta fecha.
d) Los demás impuestos y tasas municipales deben cumplir con los cuatro meses de anticipación como mínimo.','165','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":164,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"cdfa37bd1398372a5a7106a675ec808648aac9cd74090dccfc0654712a89d75b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','165','cdfa37bd1398372a5a7106a675ec808648aac9cd74090dccfc0654712a89d75b','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:166','mayalex_normativos','10_LEYES_REGLAMENTOS','Las cantidades concedidas a los contribuyentes por concepto de descuentos por pagos anticipados, deben ser registradas en la respectiva cuenta de la contabilidad municipal.','166','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":165,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"4ba6e3331c9ce1ebe76f0ac44d898fe795275b05f1a160b8eec1ed95c140e34b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','166','4ba6e3331c9ce1ebe76f0ac44d898fe795275b05f1a160b8eec1ed95c140e34b','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:167','mayalex_normativos','10_LEYES_REGLAMENTOS','En circunstancias especiales, como en el caso de terremotos, inundaciones, huelgas, conflagración bélica y otros casos fortuitos o de fuerza mayor, las municipalidades podrán prorrogar el periodo de pago de los impuestos y tasas hasta un plazo de sesenta (60) días o hasta que hayan cesado las causas que hubieren generado la calamidad o la emergencia. En tales circunstancias, la municipalidad emitirá el Acuerdo Municipal correspondiente y lo hará del conocimiento de la población por los medios de comunicación más eficaces.','167','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":166,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"c0a38a081090973eb048bc2949b4e47d3c8ce9cff5618b6faadf79068d2e9549","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','167','c0a38a081090973eb048bc2949b4e47d3c8ce9cff5618b6faadf79068d2e9549','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:168','mayalex_normativos','10_LEYES_REGLAMENTOS','Para el logro de una correcta, sana y ágil administración, las municipalidades obligadamente deberán adoptar la técnica del Presupuesto por programas. Este presupuesto debe responder al plan financiero determinado y definido para las correspondientes Corporaciones Municipales a fin de alcanzar el desarrollo global y sectorial del Municipio. Además, se debe establecer las normas y procedimientos para la recaudación de los ingresos y para la ejecución de los gastos e inversiones.','168','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":167,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"8cb8f9848157fc9c4150d6d44acae9834962b89780fae01dc13da4d411cb48db","ubicacion":["CAPITULO","DEL PRESUPUESTO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','168','8cb8f9848157fc9c4150d6d44acae9834962b89780fae01dc13da4d411cb48db','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:169','mayalex_normativos','10_LEYES_REGLAMENTOS','La estructuración del presupuesto por programas de las Municipalidades deberá hacerse siguiendo lo establecido en la Ley y el presente Reglamento, aplicando la metodología, las técnicas y principios convencionales propios de la materia.','169','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":168,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"73de542123cedd72271b05a0f706cab5ad86ce4c45e877a02f95764f35015eda","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','169','73de542123cedd72271b05a0f706cab5ad86ce4c45e877a02f95764f35015eda','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:170','mayalex_normativos','10_LEYES_REGLAMENTOS','Con base a la Ley de las Municipalidades, le corresponde al Alcalde Municipal la administración general del patrimonio del municipio e invertir los ingresos o fondos disponibles en beneficio directo de la comunidad. Por consiguiente, para alcanzar estos fines se deberán observar las siguientes etapas del proceso presupuestario:

a) Elaboración o formulación
b) Aprobación
c) Ejecución
d) Administración y
e) Evaluación','170','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":169,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"492997236edcf23662f51d4dc5b516fcc03f2b9e256bd60156ca379216d8533f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','170','492997236edcf23662f51d4dc5b516fcc03f2b9e256bd60156ca379216d8533f','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:171','mayalex_normativos','10_LEYES_REGLAMENTOS','Al Alcalde Municipal, a través del personal administrativo le compete la formulación y elaboración del presupuesto por programas anual. Para este fin, se elaboran los planes operativos anuales, así como la estimación o la proyección de los ingresos y egresos del periodo. Además de acordar la metodología de trabajo que se utilizará, se emitirán los respectivos instructivos, manuales, formularios y calendarios de actividades para llevar a cabo la formulación del presupuesto.','171','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":170,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"193a97ea76bcc67ee024599bbf11a1f8a20f11df07859ca5a6b1d3fcf6d6abbe","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','171','193a97ea76bcc67ee024599bbf11a1f8a20f11df07859ca5a6b1d3fcf6d6abbe','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:172','mayalex_normativos','10_LEYES_REGLAMENTOS','El proyecto del presupuesto de ingreso deberá presentarse estructurado y clasificado en tal forma que facilite los análisis económicos fiscales procedentes. Además, deberá mostrar el origen de las distintas fuentes de ingresos.','172','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":171,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"d8c567ee3bb35b4a42f485d0693234f77cc02db32ec4851303ac9e3f5c3eb473","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','172','d8c567ee3bb35b4a42f485d0693234f77cc02db32ec4851303ac9e3f5c3eb473','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:173','mayalex_normativos','10_LEYES_REGLAMENTOS','En la estimación de los ingresos se adoptará el principio de la universalidad, debiendo incluirse en dicha estimación todos los ingresos a que se refiere el artículo 94 de la Ley. Esta proyección debe contener el rendimiento bruto de los ingresos sin descontar el costo de la recaudación.','173','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":172,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"93f86f94db84be48b61dddca3a91b68fb79e3110ebb4a58f67175432dafd5ea3","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','173','93f86f94db84be48b61dddca3a91b68fb79e3110ebb4a58f67175432dafd5ea3','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:174','mayalex_normativos','10_LEYES_REGLAMENTOS','Los ingresos extraordinarios únicamente podrán destinarse a inversiones de capital. Esta clase de ingreso solo podrá disponerse a través de ampliaciones presupuestarias debidamente aprobadas por la Corporación.','174','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":173,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"f7942b200c8423c9df0e04a60a11dd70ce1d95bdb6d8f8884af70387d56f5766","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','174','f7942b200c8423c9df0e04a60a11dd70ce1d95bdb6d8f8884af70387d56f5766','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:175','mayalex_normativos','10_LEYES_REGLAMENTOS','Los bienes, fondos o ingresos provenientes de donaciones o de transferencias con fines específicos, no podrán ser utilizados para otras finalidades que las previamente asignadas.','175','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":174,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"c4751a3c55843df0009446b74e00639ce4607dc014f175fa87f74c356bf2de09","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','175','c4751a3c55843df0009446b74e00639ce4607dc014f175fa87f74c356bf2de09','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:176','mayalex_normativos','10_LEYES_REGLAMENTOS','El presupuesto de egresos es el reflejo de la organización municipal cuya estructura debe contener una completa y clara descripción de los programas, sub-programas, actividades y tareas de los gastos e inversiones de la Municipalidad. En este documento debe consignarse lo siguiente:

1) El Plan financiero o Programa de Ejecución para el año económico respectivo. Este plan constituye un instrumento de desarrollo del municipio y refleja las metas de trabajo, las unidades ejecutoras de los programas y las necesidades financieras que se requieren durante el periodo fiscal.
2) Un resumen general de los gastos corrientes anuales, como ser el pago de remuneración por servicios personales, sueldos, salarios, jornales etc. La compra de materiales y equipo y los pagos por contratación de servicios no personales.
3) Los pagos de las aportaciones obligatorias a instituciones públicas, como el Instituto Hondureño de Seguridad Social (IHSS), Instituto Hondureño de Formación Profesional (INFOP) Banco Municipal Autónomo (BANMA), Instituto Nacional de Jubilaciones y Pensiones de los Empleados y Funcionarios del Poder Ejecutivo (INJUPEMP). También se consignaran los pagos por los servicios públicos a las respectivas instituciones, como el Servicio Autónomo Nacional de Acueductos y Alcantarillados (SANAA), Empresa Nacional de Energía

Eléctrica (ENEE), Empresa Hondureña de Telecomunicaciones (HONDUTEL) etc.
4) Los gastos a que estuviere legalmente obligado el municipio por contratos celebrados con personas naturales o jurídicas.
5) Los egresos que resulten de las inversiones o ejecución de proyectos realizados dentro del término municipal.
6) El monto correspondiente a las transferencias al Cuerpo de Bomberos, cuando se preste este servicio en el municipio.
7) Los gastos que resulten por obligaciones contraídas por la Municipalidad y otros gastos de funcionamiento.','176','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":175,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"dca3b480d63117286f55f2f79d9807cf2458d1ee2a459c678e97cf738355fa86","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','176','dca3b480d63117286f55f2f79d9807cf2458d1ee2a459c678e97cf738355fa86','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:177','mayalex_normativos','10_LEYES_REGLAMENTOS','Los gastos necesarios para el buen funcionamiento de las Municipalidades no podrán exceder del cincuenta por ciento (50%) del total de los ingresos corrientes del periodo. Asimismo los gastos fijos ordinarios solo podrán financiarse con los ingresos ordinarios de la Municipalidad.

Para estos efectos, los gastos de funcionamiento son los que tienen un comportamiento constante durante el periodo y que son financiados con los ingresos corrientes, correspondiendo a los siguientes objetos de gasto: (1) Servicios Personales, (2) Servicios no personales, (3) Materiales y suministros, (4) Maquinaria y Equipo, incluyendo su reparación ordinaria y (5) Transferencias corrientes relacionadas a las operaciones municipales, el resto de los grupos corresponden a los gastos de capital.

Cuando se trate de programas de inversión, los objetos de gastos antes mencionados no se consideraran como gastos de funcionamiento.','177','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":176,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"2280910c4de797ed61f6fce334a6c7daa1b7d3fc737cb9f8b91c9409223c9034","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','177','2280910c4de797ed61f6fce334a6c7daa1b7d3fc737cb9f8b91c9409223c9034','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:178','mayalex_normativos','10_LEYES_REGLAMENTOS','El presupuesto de egresos tendrá como base el presupuesto de ingresos y entre ambos se mantendrá el más estricto equilibrio. En consecuencia, no podrá contraerse ningún compromiso ni efectuarse pagos fuera de las asignaciones contenidas en el Presupuesto o en convención a las disposiciones presupuestarias del mismo.','178','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":177,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"3c2faa41dab5e1c3dc30f9ac13bdf4d07a5da017985d113e3434eae56b02b748","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','178','3c2faa41dab5e1c3dc30f9ac13bdf4d07a5da017985d113e3434eae56b02b748','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:179','mayalex_normativos','10_LEYES_REGLAMENTOS','Ninguna autoridad municipal podrá hacer nombramiento de personal ni adquirir compromisos económicos sin que exista asignación presupuestaria respectiva o que esta asignación este agotada o resulte insuficiente. La contravención a esta disposición será motivo de suspensión del funcionario o empleado responsable de la acción; la reincidencia será causal de remoción del cargo, sin perjuicio de la anulación del acto y la deducción de las responsabilidades penales, civiles y administrativas que correspondan.','179','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":178,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"e06e0af9db9ddf19a5cb61d5e46487d11eb44ec357a4bc5791231a84f06b1ccd","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','179','e06e0af9db9ddf19a5cb61d5e46487d11eb44ec357a4bc5791231a84f06b1ccd','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:180','mayalex_normativos','10_LEYES_REGLAMENTOS','El Alcalde Municipal someterá a la consideración y aprobación de la Corporación

Municipal el Proyecto de Presupuesto a más tardar el 15 de septiembre de cada año. Este presupuesto debe ser aprobado lo más tarde el 30 de noviembre mediante el voto afirmativo de la mitad más uno de los miembros de la Corporación municipal.

Si por fuerza mayor u otras causas no se aprobara el Presupuesto al 31 de Diciembre, se dejará en vigencia el mismo del año que finaliza.','180','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":179,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"e899eeb6db0e774e5ed156cb76564570782527d34e161ac4677b9bd64b58fc35","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','180','e899eeb6db0e774e5ed156cb76564570782527d34e161ac4677b9bd64b58fc35','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:181','mayalex_normativos','10_LEYES_REGLAMENTOS','El Alcalde Municipal, en cualquier tiempo después de aprobado el presupuesto, puede someter a la consideración y aprobación de la Corporación Municipal las modificaciones a las asignaciones de los egresos que sean de urgente necesidad, y que requieran de ingresos adicionales no presupuestados.

La Corporación Municipal, en la aprobación de estas modificaciones deberá observar las formalidades establecidas para la aprobación del presupuesto.','181','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":180,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"711ac5690438b2623e825828acbf7cf1003311186399891689851931a38a9d66","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','181','711ac5690438b2623e825828acbf7cf1003311186399891689851931a38a9d66','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:182','mayalex_normativos','10_LEYES_REGLAMENTOS','Al final de cada periodo fiscal (enero-diciembre), el Alcalde hará la liquidación del presupuesto ejecutado. Dicha liquidación deberá ser aprobada por la Corporación Municipal en el mes de enero del año siguiente.','182','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":181,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"3145151311123f8d5c266f85fb23c40f30d0a10676f9563be5229c5474cceb01","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','182','3145151311123f8d5c266f85fb23c40f30d0a10676f9563be5229c5474cceb01','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:183','mayalex_normativos','10_LEYES_REGLAMENTOS','El 10 de enero de cada año, las Alcaldías Municipales remitirán a la Secretaría de Estado en los Despachos de Gobernación y Justicia una copia del presupuesto aprobado para el año fiscal, así como también una copia de la liquidación final del presupuesto anterior. También deberán informar sobre las modificaciones introducidas al Presupuesto aprobado.','183','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":182,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"d18e50e3f74d60e3f6a9b2d0fbc9f9ef480d8c69f211928eb15d547260802ec4","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','183','d18e50e3f74d60e3f6a9b2d0fbc9f9ef480d8c69f211928eb15d547260802ec4','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:184','mayalex_normativos','10_LEYES_REGLAMENTOS','El seguimiento financiero, el control y la ejecución del presupuesto aprobado será responsabilidad directa del Alcalde Municipal, para la cual deberá observar y cumplir con todas las disposiciones legales vigentes.','184','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":183,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"1b0025a25098b5840e246b15b3c13b447e9c2f2e09ab4836a62f114db8ba6729","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','184','1b0025a25098b5840e246b15b3c13b447e9c2f2e09ab4836a62f114db8ba6729','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:185','mayalex_normativos','10_LEYES_REGLAMENTOS','La Corporación Municipal podrá constituir fondos reintegrables o rotatorios por los montos y con los requisitos que en el respectivo acuerdo determine y estarán bajo la responsabilidad específica de un funcionario o encargado de proyecto determinado, para cuyo efecto deberá rendirse la respectiva caución, fijada y aprobada por la Contraloría General de la República.','185','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":184,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"18d16afe78053ceabdb0e9a15df9023475e57abcd0107e5f156d4306f90cb90f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','185','18d16afe78053ceabdb0e9a15df9023475e57abcd0107e5f156d4306f90cb90f','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:186','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Municipalidades, para atender los programas o planes de inversión de obras municipales, podrán contratar empréstitos y/o realizar otras operaciones financieras con instituciones crediticias nacionales, preferentemente de carácter estatal. Cuando los empréstitos se realicen con entidades extranjeras se deberá observar los procedimientos, requisitos y demás disposiciones del Decreto Legislativo N. 111-90 del 20 de Septiembre de 1990, que contiene la Ley de Crédito Público.','186','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":185,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"c8463bf38063e037fe4cd75f21ec0a549929bb4e240460755942eed2085a1086","ubicacion":["CAPITULO VI","DE LOS CRÉDITOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','186','c8463bf38063e037fe4cd75f21ec0a549929bb4e240460755942eed2085a1086','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:187','mayalex_normativos','10_LEYES_REGLAMENTOS','También las municipalidades podrán emitir bonos para el financiamiento de obras y servicios. Estos bonos son títulos valores autorizados mediante Ley, para ser colocados en los mercados de capitales, como fuente complementaria de ingresos.

Para la emisión de estos bonos, previamente se requiere la autorización del Poder Ejecutivo, por medio de la Secretaría de Hacienda y Crédito Público y el Dictamen favorable del Directorio del Banco Central de Honduras.','187','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":186,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"a2312330263b46183b3eb4ba52c19dbb70e2dbf4a6f8c406b7b5ef99abce1494","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','187','a2312330263b46183b3eb4ba52c19dbb70e2dbf4a6f8c406b7b5ef99abce1494','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:188','mayalex_normativos','10_LEYES_REGLAMENTOS','La formalización de la emisión de los bonos se hará mediante acta suscrita por el Alcalde o el funcionario municipal que ejerza la representación legal y por el Contralor General de la República.','188','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":187,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"979900e58d5c0fa1a6fd036e0e74049c620a1adb2be65234e23d5b8bb88d2758","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','188','979900e58d5c0fa1a6fd036e0e74049c620a1adb2be65234e23d5b8bb88d2758','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:189','mayalex_normativos','10_LEYES_REGLAMENTOS','Tanto para la contratación de empréstitos, como para la emisión de bonos, se requiere la aprobación mayoritaria de los miembros de la Corporación Municipal. Además de lo anterior, se deberá emitir el Acuerdo Municipal respectivo que deberá acompañarse al expediente correspondiente.','189','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":188,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"bc14f91ef9abc644c94b5d3312ebbc153af43c6d6fe7406b1b26d0b24a5bdcbf","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','189','bc14f91ef9abc644c94b5d3312ebbc153af43c6d6fe7406b1b26d0b24a5bdcbf','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:190','mayalex_normativos','10_LEYES_REGLAMENTOS','Los fondos económicos provenientes de empréstitos o bonos no podrán destinarse o utilizarse para fines distintos que para los autorizados.','190','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":189,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"05f2d917ddd8683d61bc83b293d245ebf56c5d53c9d9fd1de7120c219486124a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','190','05f2d917ddd8683d61bc83b293d245ebf56c5d53c9d9fd1de7120c219486124a','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:191','mayalex_normativos','10_LEYES_REGLAMENTOS','En el caso que la Municipalidad contrate empréstitos o emita bonos para financiar obras cuya inversión no es recuperable, esta no podrá destinar más de veinte por ciento (20%) de sus ingresos ordinarios anuales para amortizar el pago de esas deudas.','191','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":190,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"225917566e1b5a3e90b2aa184d5c66073e78f08d53dbf828245a4f45cbeffd2c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','191','225917566e1b5a3e90b2aa184d5c66073e78f08d53dbf828245a4f45cbeffd2c','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:192','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Municipalidades deberán incorporar a sus presupuestos de ingresos y egresos anuales, los fondos provenientes de los empréstitos o emisión de bonos, los proyectos de inversión programados, las cantidades de amortización de capital y el valor de los intereses a pagar en el periodo.','192','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":191,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"bf1ec49b10f24dedc47bcd424c769900b4ebda2280443e65082bc37e06d36452","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','192','bf1ec49b10f24dedc47bcd424c769900b4ebda2280443e65082bc37e06d36452','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:193','mayalex_normativos','10_LEYES_REGLAMENTOS','Las municipalidades que hayan contraído compromisos por razones de contratación de empréstitos o emisión de bonos, remitirán mensualmente a la Dirección de Crédito Público dependiendo de la Secretaría de

Hacienda y Crédito Público, un informe detallado del movimiento y estado de cada una de sus obligaciones crediticias.','193','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":192,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"5e1588fde2d7a8098ab5acc3f86638762ef23b385b51a0cc2a1b5682905f3e69","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','193','5e1588fde2d7a8098ab5acc3f86638762ef23b385b51a0cc2a1b5682905f3e69','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:194','mayalex_normativos','10_LEYES_REGLAMENTOS','La solicitud de autorización de emisión de bonos al Poder Ejecutivo deberá ser acompañado de un estudio de factibilidad técnica y económica del Proyecto que se desea financiar bajo esa modalidad, juntamente con el expediente que contengan los acuerdos de aprobación emitidos por la Corporación Municipal. Para cada tipo de proyecto deberá la Municipalidad emitir un reglamento especial que regule el manejo, la forma de inversión y recuperación, bajo la modalidad de dirección y administración de proyectos de unidades ejecutoras, dirigidas por el personal altamente calificado para cada tipo de proyecto.','194','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":193,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"3be851b64a70a9c2e8ed81b036f8b764d0cec4b35ff8ca7e2e49643b48baebd3","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','194','3be851b64a70a9c2e8ed81b036f8b764d0cec4b35ff8ca7e2e49643b48baebd3','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:195','mayalex_normativos','10_LEYES_REGLAMENTOS','En lo relativo al destino de las transferencias a que hace referencia el artículo 91 de la Ley, deberá entenderse:

a) El diez por ciento (10%) de la Transferencia servirá para fortalecer los gastos de funcionamiento de la Municipalidad; y
b) El noventa por ciento (90%) restante se destinara única y exclusivamente para cubrir gastos de inversión en proyectos de positivo beneficio para la comunidad.','195','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":194,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"684348df78de99fcda4a4551a501b5092b5cf81a3e16e523fb474efbed351f6b","ubicacion":["CAPITULO VII","DE LAS TRANSFERENCIAS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','195','684348df78de99fcda4a4551a501b5092b5cf81a3e16e523fb474efbed351f6b','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:196','mayalex_normativos','10_LEYES_REGLAMENTOS','El Ministerio de Hacienda y Crédito Público transferirá a cada una de las Municipalidades, a través de la Secretaría de Estado en los Despachos de Gobernación y Justicia, el monto de las transferencias en forma trimestral','196','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":195,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"1eebe049aaf16e39a66f54347fa5d24bc13663f0035d7f103f4777f7ac2268e9","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','196','1eebe049aaf16e39a66f54347fa5d24bc13663f0035d7f103f4777f7ac2268e9','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:197','mayalex_normativos','10_LEYES_REGLAMENTOS','Para el mejor control y administración, las Municipalidades manejarán los fondos de transferencias en cuentas especiales, debiendo incluirse en el informe trimestral que presente el Alcalde a la Corporación municipal a que hace referencia el artículo 46 de la Ley, la forma como fueron utilizados dichos fondos.

Igualmente se incluirán en el informe semestral que se presentará al Poder Ejecutivo, a través de la Secretaría de Estado en los Despachos de Gobernación y Justicia.','197','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":196,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"7390f2febb73fa54d75e6d6ccb46fbc83b44667992f841cda04385cec60c9576","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','197','7390f2febb73fa54d75e6d6ccb46fbc83b44667992f841cda04385cec60c9576','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:198','mayalex_normativos','10_LEYES_REGLAMENTOS','El incumplimiento de las disposiciones anteriores dará lugar a que la Contraloría General de la República efectúe los respectivos reparos contra los funcionarios municipales que sean responsables de la contravención.','198','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":197,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"823127f90250867ff5da095248323d566c14d89bdcf191ac50ec13226ccf7574","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','198','823127f90250867ff5da095248323d566c14d89bdcf191ac50ec13226ccf7574','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:199','mayalex_normativos','10_LEYES_REGLAMENTOS','Las obligaciones de pago que contraigan los particulares por concepto de impuesto sobre bienes Inmuebles, industrias, comercios y servicios, y contribución por mejoras constituyen un crédito preferente a favor de la Municipalidad.','199','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":198,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"a1b961a096e22b919ff9d26492a0e3fa78eef25b4b673b516637d7503aa916a8","ubicacion":["CAPITULO VII","DEL PROCEDIMIENTO PARA LA EJECUCIÓN","DE LA DEUDA MUNICIPAL"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','199','a1b961a096e22b919ff9d26492a0e3fa78eef25b4b673b516637d7503aa916a8','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:200','mayalex_normativos','10_LEYES_REGLAMENTOS','Para que la Hacienda Municipal pueda legalmente exigir el pago de las deudas que señala el artículo 111 de la Ley será necesario que sean liquidadas, de plazo vencido y, por tanto, actualmente exigibles.','200','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":199,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"1386b7b8ef614f73dc8faf6af3f1c29ba2d86aa7ae419e4570e02e7e9c86a689","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','200','1386b7b8ef614f73dc8faf6af3f1c29ba2d86aa7ae419e4570e02e7e9c86a689','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:201','mayalex_normativos','10_LEYES_REGLAMENTOS','Para la ejecución de la deuda la administración municipal dispondrá de los siguientes procedimientos:

a) El requerimiento extrajudicial escrito. Estos requerimientos se harán al deudor hasta por dos veces, a intervalos de un mes cada uno.
b) El de apremio, para ejecutar la resolución declarativa de falta de pago a favor de la administración municipal, sujetándose, a los establecido en los Artículos del 94 al 106, Titulo II, Capítulo VIII Sección Primera de la Ley de Procedimientos Administrativo; y, c) El juicio ejecutivo que se regula en el 447 y siguientes del Título I Capítulo I Sección Primera del Código de Procedimientos Civiles.','201','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":200,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"ccf1428e57cbe1e0e7810ee031986d58dea5995549d31f3e2f6f3b7dd1b74099","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','201','ccf1428e57cbe1e0e7810ee031986d58dea5995549d31f3e2f6f3b7dd1b74099','OLA13_RLMUN_1993_01',now())
