INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:202','mayalex_normativos','10_LEYES_REGLAMENTOS','Para el efecto de ejecutar la deuda municipal por la vía del requerimiento extrajudicial, no será requisito indispensable la emisión de la resolución declarativa de falta de pago, bastando para su reclamo que sea suscrito por funcionario municipal competente, en el que se le hará al deudor el conocimiento de su estado de cuenta y se le exigirá la cancelación inmediata o mediante arreglo que podrán concertar con las dependencias municipales autorizadas para tales propósitos; esta otorgara el plazo de 30 días para su cumplimiento.

Si el contribuyente no atiende este requerimiento, se le hará un segundo requerimiento, advirtiéndole que si no cancela el adeudo se procederá al cobro por la vía de apremio o la vía ejecutiva.','202','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":201,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"1ae88b9a1b904cfef58b20707446ff08c24e38fc8f1f2377c44ea25f0c22dab7","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','202','1ae88b9a1b904cfef58b20707446ff08c24e38fc8f1f2377c44ea25f0c22dab7','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:203','mayalex_normativos','10_LEYES_REGLAMENTOS','Para proceder por la vía de apremio y del juicio ejecutivo que se señala en los literales b) y c) del artículo que antecede, será necesario agotar previamente el trámite del requerimiento extrajudicial.','203','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":202,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"68dff9390c3d81556ef4bd12655375d52e8acef6b52d840c471df85660288b70","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','203','68dff9390c3d81556ef4bd12655375d52e8acef6b52d840c471df85660288b70','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:204','mayalex_normativos','10_LEYES_REGLAMENTOS','En ningún caso se utilizara la vía de apremio y la vía ejecutiva simultáneamente.','204','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":203,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"871b777022699cf6563355cd923b894384c4eb9cae2971dea919abaa8740cd36","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','204','871b777022699cf6563355cd923b894384c4eb9cae2971dea919abaa8740cd36','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:205','mayalex_normativos','10_LEYES_REGLAMENTOS','De elegirse la vía ejecutiva o de apremio, el Alcalde Municipal emitirá la Certificaron de falta de pago, en la que declarara la existencia de un crédito liquido y cierto a favor de la Municipalidad y procederá conforme a lo establecido en las letras b) y c) del artículo 201 del presente reglamento.','205','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":204,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"93f5d9726b4d94b064d8b36120218abc9602bcddd4adf304ab9cc0b2e4fc5d2a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','205','93f5d9726b4d94b064d8b36120218abc9602bcddd4adf304ab9cc0b2e4fc5d2a','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:206','mayalex_normativos','10_LEYES_REGLAMENTOS','El Alcalde Municipal y los funcionarios responsables de hacer efectivo el cobro de la deuda municipal por los procedimientos antes descritos, incurrirán en responsabilidades civil y administrativa, cuando por negligencia dejaren transcurrir el término de 5 años que establece el artículo 106 de la Ley.','206','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":205,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"2897b655573a695fb6133cda7cc5759b23f4f37af7cffa4ef7406bb8d8898bec","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','206','2897b655573a695fb6133cda7cc5759b23f4f37af7cffa4ef7406bb8d8898bec','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:207','mayalex_normativos','10_LEYES_REGLAMENTOS','Serán motivos de utilidad o interés social para decretar la expropiación de predios urbanos: la ejecución de las obras de ornato, embellecimiento, seguridad, saneamiento, construcción, reconstrucción o modernización de ciudades, aldeas, caseríos, barrios y colonias, apertura o ampliación de calles, edificaciones para mercados, rastros públicos, plazas, parques jardines de recreo, canchas deportivas, edificios públicos, contracción de delimitación y conservación de áreas verdes, planes de desarrollo urbano, la constitución de reserva para futuras extensiones de las ciudades o para la protección del sistema ecológico y en general, cualesquiera otra causa que tenga por objeto, la utilidad o el interés social.','207','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":206,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"fea96a404bd195c06ad7a65aedf8721a2ff4874b8fd1d4b20553508eaca3cc7c","ubicacion":["TITULO V","DE LA EXPROPIACION"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','207','fea96a404bd195c06ad7a65aedf8721a2ff4874b8fd1d4b20553508eaca3cc7c','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:208','mayalex_normativos','10_LEYES_REGLAMENTOS','Cuando la Municipalidad requiera ejecutar cualquiera de las obras que se mencionan en el artículo anterior, será necesario que la Corporación Municipal emita un Acuerdo declarando la utilidad o interés social de la obra y procederá a recabar la documentación e información siguientes:

a) Identificación del propietario
b) Escritura Pública de dominio
c) Gravámenes que pesan sobre el predio
d) Valor catastral y/o valor declarado
e) Monto del Impuesto sobre Bienes Inmuebles pagado en los últimos tres años.','208','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":207,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"1ccf53ee99e7740ea6be0062ed114724a7626dea022ab9c6ecca4d09e03e0df3","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','208','1ccf53ee99e7740ea6be0062ed114724a7626dea022ab9c6ecca4d09e03e0df3','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:209','mayalex_normativos','10_LEYES_REGLAMENTOS','El Alcalde emplazará al propietario o su representante legal para que en el término de 10 días hábiles presente los documentos e información mencionada en el artículo anterior.','209','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":208,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"bf27119a2fcc4db9e95b74554f1c0f1a407e5950611e0d474793d63ba73a6d49","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','209','bf27119a2fcc4db9e95b74554f1c0f1a407e5950611e0d474793d63ba73a6d49','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:210','mayalex_normativos','10_LEYES_REGLAMENTOS','A todo lo que se refiera en los trámites de expropiación se estará a lo que al efecto establece el Decreto N. 113 del 9 de Abril de 1914 Ley de Expropiación Forzosa en lo aplicable.','210','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":209,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"579c38e4db27c446e565826f7b0f252b784c357d1915a844349f2bc3ef7643b5","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','210','579c38e4db27c446e565826f7b0f252b784c357d1915a844349f2bc3ef7643b5','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:211','mayalex_normativos','10_LEYES_REGLAMENTOS','Para los efectos del Artículo 106 de la Ley, se entiende por particulares, todos aquellos que hayan constituido obligaciones contractuales o cuasicontractuales con la Municipalidad, o los que por disposición de la Ley resulten obligados a dar, hacer o no hacer alguna cosa. El plazo de prescripción será de cinco (5) años y deberá empezar a contarse:

1. En los casos que no haya disposición especial que otra cosa determine, se contará desde el día en que pudo ejercitarse el cobro.
2. Los que tengan por objeto reclamar el cumplimiento de obligaciones de capital con interés o renta, desde el último pago de la renta o interés.
3. Las acciones para exigir el cumplimiento de obligaciones declaradas por sentencia, desde la fecha que quedó firme.
4. Las que tengan el propósito de exigir la rendición de cuentas desde el día en que cesaron en sus cargos los que debían rendirlas.','211','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":210,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"174ce699a1be36565558aa7cf1b7e52daff0e1bb0fe52c3cd8bc77286c75db0f","ubicacion":["TITULO VI","DE LA PRESCRIPCION"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','211','174ce699a1be36565558aa7cf1b7e52daff0e1bb0fe52c3cd8bc77286c75db0f','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:212','mayalex_normativos','10_LEYES_REGLAMENTOS','Los acuerdos, resoluciones, ordenanzas, reglamentos, planes de arbitrios y demás actos de la administración municipal, podrán ser impugnados mediante los recursos previstos en la Ley de Procedimiento Administrativo.

Cuando la impugnación se produzca por la fijación o liquidación de cualquier tributo, multa y demás ventas o créditos municipales previamente deberán realizarse el pago de la cantidad respectiva o arreglo de pago correspondiente y procederse en la forma prevista en la sección primera, capitulo IV Titulo IV de la Ley de Jurisdicción de lo Contencioso Administrativo.','212','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":211,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"5d8075314a6c4e2d10f91f03a5d03e52cca632ce06143bfa9dff64944ea19bb5","ubicacion":["TITULO VII","DE LOS RECURSOS LEGALES","CAPITULO UNICO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','212','5d8075314a6c4e2d10f91f03a5d03e52cca632ce06143bfa9dff64944ea19bb5','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:213','mayalex_normativos','10_LEYES_REGLAMENTOS','Los actos de administración municipal podrán ser revisados de oficio por los órganos que los hayan emitido en la forma, plazos, requisitos y límites establecidos en la Ley de Procedimiento Administrativo.','213','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":212,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"f029901d7e6db4b2f414fbb1d1dc4b698456d420df58a7e902847cf17c779cc5","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','213','f029901d7e6db4b2f414fbb1d1dc4b698456d420df58a7e902847cf17c779cc5','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:214','mayalex_normativos','10_LEYES_REGLAMENTOS','Para los efectos del recurso de reposición que señala el artículo 25 numerales 11 y 14 de la Ley de Municipalidades, este se interpondrá contra las resoluciones que dicte la Corporación Municipal el Alcalde u otra autoridad inferior inmediata, dentro del término de diez (10) días siguientes al de la notificación del acto impugnado. Lo que resuelva la Corporación sobre el recurso de reposición se notificará diez (10) días después de notificada la última providencia. Transcurrido dicho término sin que la Corporación resuelva el recurso, se entenderá como desestimado y quedará expedita al recurrente la vía procedente.','214','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":213,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"0477e3ed17069e70b2bc29a3542c55523d75cd3f438d414e79f3e07267409646","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','214','0477e3ed17069e70b2bc29a3542c55523d75cd3f438d414e79f3e07267409646','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:215','mayalex_normativos','10_LEYES_REGLAMENTOS','El recurso de apelación se presentará ante la autoridad que haya emitido la resolución la que lo remitirá a la Corporación Municipal dentro del plazo de cinco (5) días hábiles siguientes a la presentación, con el expediente e informe.','215','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":214,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"a22e0d48bf6f84ab22df831179b6602f64ab8638e10363fca923d198a812b37e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','215','a22e0d48bf6f84ab22df831179b6602f64ab8638e10363fca923d198a812b37e','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:216','mayalex_normativos','10_LEYES_REGLAMENTOS','El recurso de apelación a que se refiere el Artículo 7 numeral 4 de la Ley de Municipalidades se presentará ante la Corporación Municipal, la que deberá remitir el expediente y el respectivo informe a la Gobernación Departamental, dentro de cinco días hábiles siguientes a la presentación del recurso.

El plazo para interponer este recurso, será de quince días hábiles contados de la notificación. Si transcurriere u mes desde la interposición del recurso y el apelante no se notifica de la admisión o denegación del recurso, se entenderá como desistido.','216','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":215,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"c04e54d6d63b0cd2e29882693865d986ecd14cc7033b3f1dd2fb6ed7abfb1f98","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','216','c04e54d6d63b0cd2e29882693865d986ecd14cc7033b3f1dd2fb6ed7abfb1f98','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:217','mayalex_normativos','10_LEYES_REGLAMENTOS','Cuando la Gobernación Departamental u otra autoridad emitan resoluciones, acuerdos, disposiciones, actas u órdenes que lesionen los intereses municipales, la Corporación Municipal a través de la Alcaldía podrá apelar en contra de los mismos, para cuyo efecto presentará el recurso ante la Gobernación Departamental, dentro de los (15) días de la transcripción del acto.','217','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":216,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"ad977ec27e69ff99b0964baa6c75604636f871aef91438da8e49f44424a7b995","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','217','ad977ec27e69ff99b0964baa6c75604636f871aef91438da8e49f44424a7b995','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:218','mayalex_normativos','10_LEYES_REGLAMENTOS','El escrito de apelación contendrá por lo menos los requisitos siguientes:

a) Suma que indique lo contenido;
b) La indicación del órgano al que se dirige (Gobernación Departamental);
c) Nombres, apellidos, estado, profesión u oficio y domicilio del Alcalde o de su representante, en cuyo caso deberá presentar el documento que acredite su representación.
d) Hechos conforme a los cuales se estima lesiva a los intereses de la Municipalidad con indicación precisa del acta que se recurra y sus fundamentos.','218','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":217,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"7634a098578b31b8ebf3ebfed108871fcac3258d077a790ce854bb1f89eaf3eb","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','218','7634a098578b31b8ebf3ebfed108871fcac3258d077a790ce854bb1f89eaf3eb','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:220','mayalex_normativos','10_LEYES_REGLAMENTOS','Dentro del plazo de cinco (5) días de su presentación, el Gobernador Departamental remitirá el expediente y su informe a la Secretaría de Estado en los Despachos de Gobernación y Justicia.','220','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":218,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"d9f3387a1cbe5a1d9ef103c14967e9a25aeeb1e921b7286190f1bde296ebe40a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','220','d9f3387a1cbe5a1d9ef103c14967e9a25aeeb1e921b7286190f1bde296ebe40a','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:221','mayalex_normativos','10_LEYES_REGLAMENTOS','La Secretaría de Estado en los Despachos de Gobernación y Justicia una vez que haya recibido el expediente y si hubiere hecho que probar, abrirá el juicio a pruebas por un término de quince idas, dentro del cual podrá disponer de oficio cuanta prueba sea pertinente para la más acertada decisión del asunto.','221','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":219,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"f1b902dffdf396ff666cdeaa80d216219e9dc416c3151926447b933faa890221","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','221','f1b902dffdf396ff666cdeaa80d216219e9dc416c3151926447b933faa890221','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:222','mayalex_normativos','10_LEYES_REGLAMENTOS','Una vez practicada la prueba a que se alude en el artículo anterior se dará vista de las actuaciones a las partes para que dentro del plazo común de diez (10) días, aleguen sobre todo lo actuado y el valor y alcance de las pruebas producidas.','222','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":220,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"50f9d6a69994fd67820ec01298b7ef8fe97b4ee280b1917c58459c847c017303","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','222','50f9d6a69994fd67820ec01298b7ef8fe97b4ee280b1917c58459c847c017303','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:223','mayalex_normativos','10_LEYES_REGLAMENTOS','Vencido el plazo a que se refiere el artículo que antecede, la Secretaría de Estado en los Despachos de Gobernación y Justicia emitirá el acuerdo que corresponda, confirmando, anulando o modificando la resolución impugnada.','223','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":221,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"889c8d234af92b0c8a98c9b165caa599f31de70cc90654ab08ebbe683bfe2027","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','223','889c8d234af92b0c8a98c9b165caa599f31de70cc90654ab08ebbe683bfe2027','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:224','mayalex_normativos','10_LEYES_REGLAMENTOS','Previo a la planificación y ejecución de un proyecto de obra pública comprendido en el término municipal que deba realizar cualquier institución estatal incluso las descentralizadas, deberá requerir de la Corporación Municipal su opinión sobre la conveniencia del Proyecto.','224','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":222,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"a5effb53606df10883c8fa3357937a1f37495f2c58888508a6d6b5f76cbf7921","ubicacion":["TITULO VIII","DISPOSICIONES GENERALES","CAPITULO UNICO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','224','a5effb53606df10883c8fa3357937a1f37495f2c58888508a6d6b5f76cbf7921','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:225','mayalex_normativos','10_LEYES_REGLAMENTOS','Cuando se omitiera la consulta a la Corporación Municipal o habiéndola proporcionado fuere ignorada por el organismo ejecutor, la municipalidad lo hará del conocimiento del Gobernador Departamental para que informe de inmediato a la Secretaría de Estado en los Despachos de Gobernación y Justicia para su debida intervención.','225','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":223,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"268f3b16313d031cf2f2657d0573e589d235a1b9029803d2bf8dc63e72dd6018","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','225','268f3b16313d031cf2f2657d0573e589d235a1b9029803d2bf8dc63e72dd6018','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:226','mayalex_normativos','10_LEYES_REGLAMENTOS','Cuando la Ley señala que el Alcalde tiene la facultad de nombrar, ascender, trasladar y destituir al personal, deberá entenderse que su ingreso, o reclutamiento y remoción se hace por decisión exclusiva del Alcalde o sea sin la intervención de la Corporación, pero para todas las acciones mencionadas, el Alcalde estará sujeto al procedimiento prescrito por la Ley del Servicio Civil y su Reglamento en lo aplicable.','226','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":224,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"f28f91a90fee475df00dee5efcbe57e3be7812a13b137ab58695602ee8ca7fdf","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','226','f28f91a90fee475df00dee5efcbe57e3be7812a13b137ab58695602ee8ca7fdf','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:227','mayalex_normativos','10_LEYES_REGLAMENTOS','Las Municipalidades recaudarán los impuestos, tasas por servicios contribuciones y demás tributos locales mediante el uso de comprobantes o recibos de pago.

Las Municipalidades que cuenten con la capacidad suficiente para mandar a imprimir sus propios comprobantes y no requieran el uso de las especies municipales que distribuye la Dirección General de Asesoría y Asistencia Técnica Municipal, podrán preparar los modelos o formas correspondientes, sometiéndolos a dictamen de la Contraloría General de la República.

Cada vez que la Municipalidad ordene la impresión de estos comprobantes, deberá comunicarlo a la Contraloría General de la República y remitirle además, copia del Acta de Emisión que se levante cuando sean recibidos de la empresa impresora.','227','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":225,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"f61d1eb4532e8db23b2e35700cd4c08edd04032e01f4bba4256e15514fa3d0a8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','227','f61d1eb4532e8db23b2e35700cd4c08edd04032e01f4bba4256e15514fa3d0a8','OLA13_RLMUN_1993_01',now()),
('OLA13_RLMUN_1993_01:REGLAMENTO_LEY_MUNICIPALIDADES:228','mayalex_normativos','10_LEYES_REGLAMENTOS','El presente Reglamento General entrará en vigencia al día siguiente de su Publicación en el Diario Oficial “La Gaceta”.','228','Reglamento General de la Ley de Municipalidades de Honduras (Acuerdo No. 018-93)','{"norm_id":"HN:REGLAMENTO_LEY_MUNICIPALIDADES","instrumento_id":"REGLAMENTO_LEY_MUNICIPALIDADES","ingest_batch":"OLA13_RLMUN_1993_01","ola":"OLA13","ordinal":226,"decreto":"Acuerdo 018-93","texto_origen":"PDF_CONSOLIDADO_AMHON_SANEADO","edicion_fuente":"Edición de la Asociación de Municipios de Honduras (AMHON), «LEY DE MUNICIPALIDADES.pdf» (2011), págs. 112–221: Reglamento General de la Ley de Municipalidades (Acuerdo No. 018-93, La Gaceta del 18-feb-1993), sin reformas anotadas; separado de la Ley (lote OLA13_LMUN_2009_01).","pdf_sha256":"b711caf62cc5996650e18a4294ed761501b7a9066060dc9555ff34234ec181ee","article_sha256":"057eaf805a39a3add89b3046b25bc7a6e84ec2635d5007e2be0a0f309457d8a9","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición AMHON del Acuerdo 018-93, sin reformas anotadas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'REGLAMENTO_LEY_MUNICIPALIDADES','228','057eaf805a39a3add89b3046b25bc7a6e84ec2635d5007e2be0a0f309457d8a9','OLA13_RLMUN_1993_01',now())
