DO $do$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA13_RLMUN_1993_01' AND metadata->>'norm_id' = 'HN:REGLAMENTO_LEY_MUNICIPALIDADES'
    AND instrumento_id = 'REGLAMENTO_LEY_MUNICIPALIDADES' AND jurisdiccion = 'HN' AND encode(sha256(convert_to(contenido, 'UTF8')), 'hex') = hash_contenido AND revision_pendiente = true AND es_norma_vigente IS NULL;
